{
  "kind": "method",
  "name": "createForumTopic",
  "url": "https://core.telegram.org/bots/api#createforumtopic",
  "description": "Use this method to create a topic in a forum supergroup chat or a private chat with a user. In the case of a supergroup chat the bot must be an administrator in the chat for this to work and must have the can_manage_topics administrator right. In the case of a private chat, a link to the topic can be created in the format `https://t.me/<bot_username>/<message_thread_id>`; the link opens the topic only for the user. Returns information about the created topic as a ForumTopic object.",
  "returns": "Returns information about the created topic as a ForumTopic object.",
  "params": {
    "chat_id": {
      "type": "Integer or String",
      "required": true,
      "description": "Unique identifier for the target chat or username of the target supergroup in the format `@username`"
    },
    "name": {
      "type": "String",
      "required": true,
      "description": "Topic name, 1-128 characters",
      "length": {
        "min": 1,
        "max": 128,
        "unit": "characters"
      }
    },
    "icon_color": {
      "type": "Integer",
      "required": false,
      "description": "Color of the topic icon in RGB format. Currently, must be one of 7322096 (0x6FB9F0), 16766590 (0xFFD67E), 13338331 (0xCB86DB), 9367192 (0x8EEE98), 16749490 (0xFF93B2), or 16478047 (0xFB6F5F)."
    },
    "icon_custom_emoji_id": {
      "type": "String",
      "required": false,
      "description": "Unique identifier of the custom emoji shown as the topic icon. Use getForumTopicIconStickers to get all allowed custom emoji identifiers."
    }
  },
  "changes": [
    {
      "version": "9.4",
      "date": "February 9, 2026",
      "url": "https://core.telegram.org/bots/api-changelog#february-9-2026",
      "text": "Allowed bots to create topics in private chats using the method createForumTopic."
    },
    {
      "version": "6.3",
      "date": "November 5, 2022",
      "url": "https://core.telegram.org/bots/api-changelog#november-5-2022",
      "text": "Added the methods createForumTopic, editForumTopic, closeForumTopic, reopenForumTopic, deleteForumTopic, unpinAllForumTopicMessages, and getForumTopicIconStickers for forum topic management."
    }
  ],
